//! Build-time codegen for `stations.json`: D57 posts and interactive decor.
//! Generated from `maps-server.zip` filtered by `free2play.csv`
//! (see `gamedata/data/stations.json` header comment in the generator).
//! Dump order kept (kind, x, z, level).

/// Render `stations_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "stations");
    let rows = crate::dump_rows(&parsed, "stations");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/stations.json - do not edit.\n\
         pub static ALL: &[super::StaticStation] = &[\n",
    );
    for row in rows {
        generated.push_str(&format!(
            "    super::StaticStation {{ kind: \"{}\", loc: \"{}\", loc_id: {}, x: {}, z: {}, level: {} }},\n",
            crate::escape_for_rust_literal(row.get("kind").as_str().unwrap_or("")),
            crate::escape_for_rust_literal(row.get("loc").as_str().unwrap_or("")),
            row.get("loc_id").as_i64().unwrap_or(-1),
            row.get("x").as_i64().unwrap_or(0),
            row.get("z").as_i64().unwrap_or(0),
            row.get("level").as_i64().unwrap_or(0),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("stations_generated.rs", &generated);
}
